package initdb

// pgProcInitdbOverride is the state a PostgreSQL 18.3 initdb leaves on a
// built-in function that system_functions.sql re-creates after bootstrap
// (pgProcInitdbOverrides, generated by scripts/gen-pg-proc-initdb-overrides.py):
// argument DEFAULTs and names, SQL-language bodies stored as a prosqlbody node
// tree with prosrc '', and the cost/strictness/volatility/parallel/language it
// declares. pgProcRow applies it over the pg_proc.dat attributes
// (M0149-0001g slice 16).
type pgProcInitdbOverride struct {
	Src          string
	SqlBody      string // nodeToString of the parsed body; "" = NULL
	NArgDefaults int
	ArgDefaults  string // nodeToString of the default-expression List; "" = NULL
	ArgNames     []string
	Cost, Rows   int64
	Strict       bool
	Volatile     byte
	Parallel     byte
	Lang         uint32
}
